import numpy as np
def f(inp):
    a=np.array(inp); H,W=a.shape; bg=np.bincount(a.flatten()).argmax()
    # find pattern block: first non-bg cell scan
    cells=[(i,j) for i in range(H) for j in range(W) if a[i][j]!=bg and a[i][j]!=0]
    rows=[i for i,_ in cells]; cols=[j for _,j in cells]
    r0,c0=min(rows),min(cols); r1=max(rows),c1=max(cols)
    pat=a[r0:r1+1,c0:c1+1]
    out=a.copy()
    # zero blocks: connected components of 0 (4-conn), exclude border
    import collections
    seen=[[False]*W for _ in range(H)]
    comps=[]
    for i in range(H):
        for j in range(W):
            if a[i][j]==0 and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; comp=[]
                while st:
                    y,x=st.pop(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and a[ny][nx]==0 and not seen[ny][nx]:
                            seen[ny][nx]=True; st.append((ny,nx))
                if len(comp)>5: comps.append((comp))
    for comp in comps:
        ys=[y for y,_ in comp]; xs=[x for _,x in comp]
        r0b,r1b,c0b,c1b=min(ys),max(ys),min(xs),max(xs)
        h,w=r1b-r0b+1,c1b-c0b+1
        sub=pat[:h,:w]  # crop at top-left of pattern bbox -> but pattern may be 5x5 into 4x4
        out[r0b:r0b+h,c0b:c0b+w]=sub
    return out.tolist()
